contracts/AgencyRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AgencyRegistry
 * @dev Central registry for recruitment agencies with dynamic trust scoring
 * Acts as the on-chain, public directory of all registered and verified recruitment agencies
 */
contract AgencyRegistry is Ownable {
    struct Agency {
        address owner; // The agency's primary wallet address
        string name;
        string did; // Agency's DID for identity verification
        uint256 trustScore; // Score from 0-1000 (scaled by 10 for precision)
        bool isRegistered;
        uint256 registeredAt;
        uint256 lastScoreUpdate;
    }

    // Insurance bond structure for Pillar 2 compliance
    struct InsuranceBond {
        string policyNumber;
        uint256 coverageAmount;
        uint256 expiryDate;
        address insuranceProvider;
        bool isActive;
        string credentialJWT; // Verifiable Credential for the bond
        uint256 lastUpdated;
    }

    // Mapping from agency address to agency data
    mapping(address => Agency) public agencies;

    // Mapping from agency address to insurance bond
    mapping(address => InsuranceBond) public agencyInsurance;

    // Array to keep track of all registered agencies
    address[] public agencyList;

    // Mapping to check if an agency is in the list (for gas optimization)
    mapping(address => bool) public isInList;

    // Events
    event AgencyRegistered(
        address indexed agencyAddress, 
        string name, 
        string did, 
        uint256 initialTrustScore
    );

    event TrustScoreUpdated(
        address indexed agencyAddress, 
        uint256 oldScore, 
        uint256 newScore,
        uint256 timestamp
    );

    event AgencyUpdated(
        address indexed agencyAddress,
        string newName,
        string newDid
    );

    event InsuranceBondUpdated(
        address indexed agencyAddress,
        string policyNumber,
        uint256 coverageAmount,
        uint256 expiryDate,
        address indexed insuranceProvider
    );

    event InsuranceBondExpired(
        address indexed agencyAddress,
        string policyNumber
    );

    // Modifiers
    modifier onlyRegisteredAgency(address _agencyAddress) {
        require(agencies[_agencyAddress].isRegistered, "Agency not registered");
        _;
    }

    constructor() Ownable(msg.sender) {
        // Constructor sets the deployer as the owner
    }

    /**
     * @dev Register a new recruitment agency
     * Only the owner (regulator/BMET contract) can add new agencies
     * @param _agencyAddress The agency's wallet address
     * @param _name The agency's name
     * @param _did The agency's DID for identity verification
     */
    function registerAgency(
        address _agencyAddress, 
        string memory _name,
        string memory _did
    ) public onlyOwner {
        require(_agencyAddress != address(0), "Invalid agency address");
        require(bytes(_name).length > 0, "Agency name cannot be empty");
        require(bytes(_did).length > 0, "Agency DID cannot be empty");
        require(!agencies[_agencyAddress].isRegistered, "Agency already registered");

        // Create new agency with default trust score of 100.0 (1000 scaled)
        agencies[_agencyAddress] = Agency({
            owner: _agencyAddress,
            name: _name,
            did: _did,
            trustScore: 1000, // Default score: 100.0 (scaled by 10)
            isRegistered: true,
            registeredAt: block.timestamp,
            lastScoreUpdate: block.timestamp
        });

        // Add to agency list if not already present
        if (!isInList[_agencyAddress]) {
            agencyList.push(_agencyAddress);
            isInList[_agencyAddress] = true;
        }

        emit AgencyRegistered(_agencyAddress, _name, _did, 1000);
    }

    /**
     * @dev Update an agency's trust score
     * Only the owner (backend service wallet) can update scores
     * @param _agencyAddress The agency's address
     * @param _newScore The new trust score (scaled by 10, so 1000 = 100.0)
     */
    function updateTrustScore(
        address _agencyAddress, 
        uint256 _newScore
    ) public onlyOwner onlyRegisteredAgency(_agencyAddress) {
        require(_newScore <= 2000, "Trust score cannot exceed 200.0"); // Max score 200.0

        uint256 oldScore = agencies[_agencyAddress].trustScore;
        agencies[_agencyAddress].trustScore = _newScore;
        agencies[_agencyAddress].lastScoreUpdate = block.timestamp;

        emit TrustScoreUpdated(_agencyAddress, oldScore, _newScore, block.timestamp);
    }

    /**
     * @dev Update agency information (name and DID)
     * Only the owner can update agency information
     * @param _agencyAddress The agency's address
     * @param _newName The new agency name
     * @param _newDid The new agency DID
     */
    function updateAgencyInfo(
        address _agencyAddress,
        string memory _newName,
        string memory _newDid
    ) public onlyOwner onlyRegisteredAgency(_agencyAddress) {
        require(bytes(_newName).length > 0, "Agency name cannot be empty");
        require(bytes(_newDid).length > 0, "Agency DID cannot be empty");

        agencies[_agencyAddress].name = _newName;
        agencies[_agencyAddress].did = _newDid;

        emit AgencyUpdated(_agencyAddress, _newName, _newDid);
    }

    /**
     * @dev Get agency information
     * @param _agencyAddress The agency's address
     * @return agency The complete agency information
     */
    function getAgency(address _agencyAddress) 
        public 
        view 
        onlyRegisteredAgency(_agencyAddress)
        returns (Agency memory agency) 
    {
        return agencies[_agencyAddress];
    }

    /**
     * @dev Get agency trust score
     * @param _agencyAddress The agency's address
     * @return trustScore The agency's current trust score (scaled by 10)
     */
    function getTrustScore(address _agencyAddress) 
        public 
        view 
        onlyRegisteredAgency(_agencyAddress)
        returns (uint256 trustScore) 
    {
        return agencies[_agencyAddress].trustScore;
    }

    /**
     * @dev Get the total number of registered agencies
     * @return count The number of registered agencies
     */
    function getAgencyCount() public view returns (uint256 count) {
        return agencyList.length;
    }

    /**
     * @dev Get agency address by index
     * @param _index The index in the agency list
     * @return agencyAddress The agency's address
     */
    function getAgencyByIndex(uint256 _index) 
        public 
        view 
        returns (address agencyAddress) 
    {
        require(_index < agencyList.length, "Index out of bounds");
        return agencyList[_index];
    }

    /**
     * @dev Get all registered agency addresses
     * @return addresses Array of all registered agency addresses
     */
    function getAllAgencies() public view returns (address[] memory addresses) {
        return agencyList;
    }

    /**
     * @dev Check if an agency is registered
     * @param _agencyAddress The agency's address to check
     * @return isRegistered True if the agency is registered
     */
    function isAgencyRegistered(address _agencyAddress) 
        public 
        view 
        returns (bool) 
    {
        return agencies[_agencyAddress].isRegistered;
    }

    /**
     * @dev Get agencies with trust score above a threshold
     * @param _minScore Minimum trust score threshold (scaled by 10)
     * @return qualifiedAgencies Array of agency addresses meeting the criteria
     */
    function getQualifiedAgencies(uint256 _minScore) 
        public 
        view 
        returns (address[] memory qualifiedAgencies) 
    {
        uint256 count = 0;

        // First pass: count qualified agencies
        for (uint256 i = 0; i < agencyList.length; i++) {
            if (agencies[agencyList[i]].trustScore >= _minScore) {
                count++;
            }
        }

        // Second pass: populate the result array
        qualifiedAgencies = new address[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < agencyList.length; i++) {
            if (agencies[agencyList[i]].trustScore >= _minScore) {
                qualifiedAgencies[index] = agencyList[i];
                index++;
            }
        }

        return qualifiedAgencies;
    }

    /**
     * @dev Get top N agencies by trust score
     * @param _limit Maximum number of agencies to return
     * @return topAgencies Array of top agency addresses
     * @return scores Array of corresponding trust scores
     */
    function getTopAgencies(uint256 _limit) 
        public 
        view 
        returns (address[] memory topAgencies, uint256[] memory scores) 
    {
        uint256 totalAgencies = agencyList.length;
        uint256 returnCount = _limit > totalAgencies ? totalAgencies : _limit;

        topAgencies = new address[](returnCount);
        scores = new uint256[](returnCount);

        // Simple selection sort for top N (efficient for small N)
        address[] memory tempAgencies = new address[](totalAgencies);
        uint256[] memory tempScores = new uint256[](totalAgencies);

        // Copy all agencies and scores
        for (uint256 i = 0; i < totalAgencies; i++) {
            tempAgencies[i] = agencyList[i];
            tempScores[i] = agencies[agencyList[i]].trustScore;
        }

        // Sort and select top N
        for (uint256 i = 0; i < returnCount; i++) {
            uint256 maxIndex = i;

            // Find the maximum in remaining elements
            for (uint256 j = i + 1; j < totalAgencies; j++) {
                if (tempScores[j] > tempScores[maxIndex]) {
                    maxIndex = j;
                }
            }

            // Swap if needed
            if (maxIndex != i) {
                (tempAgencies[i], tempAgencies[maxIndex]) = (tempAgencies[maxIndex], tempAgencies[i]);
                (tempScores[i], tempScores[maxIndex]) = (tempScores[maxIndex], tempScores[i]);
            }

            topAgencies[i] = tempAgencies[i];
            scores[i] = tempScores[i];
        }

        return (topAgencies, scores);
    }

    /**
     * @dev Update insurance bond for an agency (Owner only)
     * @param _agencyAddress The agency's address
     * @param _policyNumber Insurance policy number
     * @param _coverageAmount Coverage amount
     * @param _expiryDate Expiry date timestamp
     * @param _insuranceProvider Insurance provider address
     * @param _credentialJWT Verifiable credential JWT
     */
    function updateInsuranceBond(
        address _agencyAddress,
        string memory _policyNumber,
        uint256 _coverageAmount,
        uint256 _expiryDate,
        address _insuranceProvider,
        string memory _credentialJWT
    ) public onlyOwner onlyRegisteredAgency(_agencyAddress) {
        require(bytes(_policyNumber).length > 0, "Policy number cannot be empty");
        require(_coverageAmount > 0, "Coverage amount must be greater than zero");
        require(_expiryDate > block.timestamp, "Expiry date must be in the future");
        require(_insuranceProvider != address(0), "Insurance provider address cannot be zero");

        agencyInsurance[_agencyAddress] = InsuranceBond({
            policyNumber: _policyNumber,
            coverageAmount: _coverageAmount,
            expiryDate: _expiryDate,
            insuranceProvider: _insuranceProvider,
            isActive: true,
            credentialJWT: _credentialJWT,
            lastUpdated: block.timestamp
        });

        emit InsuranceBondUpdated(_agencyAddress, _policyNumber, _coverageAmount, _expiryDate, _insuranceProvider);
    }

    /**
     * @dev Verify insurance status for an agency
     * @param _agencyAddress The agency's address
     * @return isValid True if insurance is valid and not expired
     */
    function verifyInsuranceStatus(address _agencyAddress) public view returns (bool isValid) {
        InsuranceBond memory bond = agencyInsurance[_agencyAddress];
        return bond.isActive && bond.expiryDate > block.timestamp && bond.coverageAmount > 0;
    }

    /**
     * @dev Get insurance coverage amount for an agency
     * @param _agencyAddress The agency's address
     * @return coverageAmount The coverage amount
     */
    function getInsuranceCoverage(address _agencyAddress) public view returns (uint256 coverageAmount) {
        return agencyInsurance[_agencyAddress].coverageAmount;
    }

    /**
     * @dev Get complete insurance bond information
     * @param _agencyAddress The agency's address
     * @return bond The complete insurance bond information
     */
    function getInsuranceBond(address _agencyAddress) public view returns (InsuranceBond memory bond) {
        return agencyInsurance[_agencyAddress];
    }

    /**
     * @dev Check if agency has valid insurance bond
     * @param _agencyAddress The agency's address
     * @return hasValidInsurance True if agency has valid, non-expired insurance
     */
    function hasValidInsurance(address _agencyAddress) public view returns (bool hasValidInsurance) {
        InsuranceBond memory bond = agencyInsurance[_agencyAddress];
        return bond.isActive && 
               bond.expiryDate > block.timestamp && 
               bond.coverageAmount > 0 && 
               bytes(bond.policyNumber).length > 0;
    }

    /**
     * @dev Deactivate insurance bond (Owner only)
     * @param _agencyAddress The agency's address
     */
    function deactivateInsuranceBond(address _agencyAddress) public onlyOwner onlyRegisteredAgency(_agencyAddress) {
        InsuranceBond storage bond = agencyInsurance[_agencyAddress];
        require(bond.isActive, "Insurance bond is already inactive");

        bond.isActive = false;
        bond.lastUpdated = block.timestamp;

        emit InsuranceBondExpired(_agencyAddress, bond.policyNumber);
    }

    /**
     * @dev Get agencies with valid insurance bonds
     * @return insuredAgencies Array of agency addresses with valid insurance
     */
    function getInsuredAgencies() public view returns (address[] memory insuredAgencies) {
        uint256 count = 0;

        // First pass: count agencies with valid insurance
        for (uint256 i = 0; i < agencyList.length; i++) {
            if (hasValidInsurance(agencyList[i])) {
                count++;
            }
        }

        // Second pass: populate the result array
        insuredAgencies = new address[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < agencyList.length; i++) {
            if (hasValidInsurance(agencyList[i])) {
                insuredAgencies[index] = agencyList[i];
                index++;
            }
        }

        return insuredAgencies;
    }

    /**
     * @dev Get agencies with expired insurance bonds
     * @return expiredAgencies Array of agency addresses with expired insurance
     */
    function getAgenciesWithExpiredInsurance() public view returns (address[] memory expiredAgencies) {
        uint256 count = 0;

        // First pass: count agencies with expired insurance
        for (uint256 i = 0; i < agencyList.length; i++) {
            InsuranceBond memory bond = agencyInsurance[agencyList[i]];
            if (bond.coverageAmount > 0 && (bond.expiryDate <= block.timestamp || !bond.isActive)) {
                count++;
            }
        }

        // Second pass: populate the result array
        expiredAgencies = new address[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < agencyList.length; i++) {
            InsuranceBond memory bond = agencyInsurance[agencyList[i]];
            if (bond.coverageAmount > 0 && (bond.expiryDate <= block.timestamp || !bond.isActive)) {
                expiredAgencies[index] = agencyList[i];
                index++;
            }
        }

        return expiredAgencies;
    }

    /**
     * @dev Get qualified agencies with both good trust score and valid insurance
     * @param _minScore Minimum trust score threshold
     * @return qualifiedAgencies Array of fully qualified agency addresses
     */
    function getFullyQualifiedAgencies(uint256 _minScore) public view returns (address[] memory qualifiedAgencies) {
        uint256 count = 0;

        // First pass: count fully qualified agencies
        for (uint256 i = 0; i < agencyList.length; i++) {
            if (agencies[agencyList[i]].trustScore >= _minScore && hasValidInsurance(agencyList[i])) {
                count++;
            }
        }

        // Second pass: populate the result array
        qualifiedAgencies = new address[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < agencyList.length; i++) {
            if (agencies[agencyList[i]].trustScore >= _minScore && hasValidInsurance(agencyList[i])) {
                qualifiedAgencies[index] = agencyList[i];
                index++;
            }
        }

        return qualifiedAgencies;
    }
}

contracts/Anchor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title Anchor
 * @dev Simple contract for anchoring Merkle roots from private Besu chain to public chain
 * Designed to be extremely gas-efficient for batch anchoring operations
 */
contract Anchor is Ownable {
    // State variables
    uint256 public batchCounter;
    mapping(uint256 => bytes32) public anchoredRoots;

    // Events
    event BatchAnchored(uint256 indexed batchId, bytes32 indexed root, address sender);

    /**
     * @dev Constructor sets the contract deployer as the owner
     */
    constructor() Ownable(msg.sender) {
        batchCounter = 0;
    }

    /**
     * @dev Anchors a new Merkle root batch
     * @param _merkleRoot The Merkle root hash to anchor
     * Only callable by the contract owner (backend service)
     */
    function anchorNewBatch(bytes32 _merkleRoot) external onlyOwner {
        require(_merkleRoot != bytes32(0), "Merkle root cannot be zero");

        // Increment batch counter
        batchCounter++;

        // Store the Merkle root
        anchoredRoots[batchCounter] = _merkleRoot;

        // Emit event for off-chain monitoring
        emit BatchAnchored(batchCounter, _merkleRoot, msg.sender);
    }

    /**
     * @dev Returns the Merkle root for a specific batch ID
     * @param batchId The batch ID to query
     * @return The Merkle root hash for the specified batch
     */
    function getMerkleRoot(uint256 batchId) external view returns (bytes32) {
        require(batchId > 0 && batchId <= batchCounter, "Invalid batch ID");
        return anchoredRoots[batchId];
    }

    /**
     * @dev Returns the latest batch ID and its Merkle root
     * @return batchId The latest batch ID
     * @return merkleRoot The latest Merkle root
     */
    function getLatestBatch() external view returns (uint256 batchId, bytes32 merkleRoot) {
        require(batchCounter > 0, "No batches anchored yet");
        return (batchCounter, anchoredRoots[batchCounter]);
    }

    /**
     * @dev Checks if a specific batch ID exists
     * @param batchId The batch ID to check
     * @return True if the batch exists, false otherwise
     */
    function batchExists(uint256 batchId) external view returns (bool) {
        return batchId > 0 && batchId <= batchCounter && anchoredRoots[batchId] != bytes32(0);
    }
}

contracts/EmploymentContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title EmploymentContract
 * @dev Represents a legally-binding employment agreement between a worker and employer
 * Acts as digital escrow for trust and immutable log of agreement lifecycle
 */
contract EmploymentContract {
    // Contract status enumeration
    enum ContractStatus {
        Proposed,
        Active,
        Disputed,
        Completed
    }

    // Payment status enumeration
    enum PaymentStatus {
        OnTime,
        Overdue,
        Disputed
    }

    // State variables
    address public worker;
    address public employer;
    uint256 public salary;
    uint256 public payFrequency; // Payment interval in days (e.g., 30 for monthly)
    uint256 public nextPaymentDueDate; // Timestamp of next expected payment
    uint256 public escrowRequirement; // Required escrow amount (1-2 months salary)
    bool public escrowDeposited; // Whether escrow has been deposited
    address public escrowContract; // Address of associated escrow contract
    string public termsHash; // IPFS Content ID (CID)
    ContractStatus public status;
    PaymentStatus public currentPaymentStatus;
    bool public workerSigned;
    bool public employerSigned;
    address public regulator; // Trusted third party for dispute resolution

    // Payment tracking
    struct Payment {
        uint256 amount;
        uint256 timestamp;
        string transactionHash; // Optional: real-world bank transfer hash
    }
    Payment[] public payments;

    // Credential status tracking
    mapping(string => string) public credentialStatuses;
    mapping(string => address) public credentialIssuers;

    // Events
    event ContractSigned(address indexed worker, address indexed employer);
    event StatusChanged(ContractStatus newStatus);
    event PaymentStatusChanged(PaymentStatus newStatus);
    event PaymentRecorded(uint256 amount, uint256 timestamp, string transactionHash);
    event PaymentOverdue(uint256 dueDate, uint256 currentTime);
    event DisputeRaised(address indexed worker);
    event EscrowRequirementSet(uint256 amount);
    event EscrowDeposited(address indexed escrowContract, uint256 amount);
    event EscrowLinked(address indexed escrowContract);
    event CredentialStatusUpdated(string indexed credentialId, string status, address indexed updatedBy);

    // Modifiers
    modifier onlyWorker() {
        require(msg.sender == worker, "Only worker can call this function");
        _;
    }

    modifier onlyEmployer() {
        require(msg.sender == employer, "Only employer can call this function");
        _;
    }

    modifier onlyParties() {
        require(
            msg.sender == worker || msg.sender == employer,
            "Only contract parties can call this function"
        );
        _;
    }

    modifier onlyRegulator() {
        require(msg.sender == regulator, "Only regulator can call this function");
        _;
    }

    modifier onlyWhenActive() {
        require(status == ContractStatus.Active, "Contract must be active");
        _;
    }

    modifier onlyWhenProposed() {
        require(status == ContractStatus.Proposed, "Contract must be in proposed state");
        _;
    }

    /**
     * @dev Constructor initializes the contract with basic parameters
     * @param _worker Address of the migrant worker
     * @param _employer Address of the employer/agency
     * @param _salary Agreed-upon salary per pay period
     * @param _payFrequency Payment interval in days (e.g., 30 for monthly)
     * @param _termsHash IPFS CID hash pointing to full contract document
     * @param _regulator Address of trusted third party for dispute resolution
     */
    constructor(
        address _worker,
        address _employer,
        uint256 _salary,
        uint256 _payFrequency,
        string memory _termsHash,
        address _regulator
    ) {
        require(_worker != address(0), "Worker address cannot be zero");
        require(_employer != address(0), "Employer address cannot be zero");
        require(_regulator != address(0), "Regulator address cannot be zero");
        require(_worker != _employer, "Worker and employer must be different");
        require(_salary > 0, "Salary must be greater than zero");
        require(_payFrequency > 0, "Pay frequency must be greater than zero");
        require(bytes(_termsHash).length > 0, "Terms hash cannot be empty");

        worker = _worker;
        employer = _employer;
        salary = _salary;
        payFrequency = _payFrequency;
        termsHash = _termsHash;
        regulator = _regulator;
        status = ContractStatus.Proposed;
        currentPaymentStatus = PaymentStatus.OnTime;
        workerSigned = false;
        employerSigned = false;
        escrowDeposited = false;

        // Set escrow requirement to 2 months salary by default
        escrowRequirement = salary * 2;
        emit EscrowRequirementSet(escrowRequirement);
    }

    /**
     * @dev Allows worker or employer to sign the contract
     * Automatically activates contract when both parties have signed and escrow is deposited
     */
    function signContract() external onlyParties onlyWhenProposed {
        if (msg.sender == worker) {
            require(!workerSigned, "Worker has already signed");
            workerSigned = true;
        } else if (msg.sender == employer) {
            require(!employerSigned, "Employer has already signed");
            employerSigned = true;
        }

        // If both parties have signed and escrow is deposited, activate the contract
        if (workerSigned && employerSigned && escrowDeposited) {
            status = ContractStatus.Active;
            // Set the first payment due date
            nextPaymentDueDate = block.timestamp + (payFrequency * 1 days);
            emit ContractSigned(worker, employer);
            emit StatusChanged(ContractStatus.Active);
        }
    }

    /**
     * @dev Allows employer to record a salary payment
     * @param amount The payment amount being recorded
     * @param transactionHash Optional real-world bank transfer hash
     */
    function recordPayment(uint256 amount, string memory transactionHash) external onlyEmployer onlyWhenActive {
        require(amount > 0, "Payment amount must be greater than zero");

        Payment memory newPayment = Payment({
            amount: amount,
            timestamp: block.timestamp,
            transactionHash: transactionHash
        });

        payments.push(newPayment);

        // Update next payment due date
        nextPaymentDueDate = block.timestamp + (payFrequency * 1 days);

        // Update payment status to OnTime
        if (currentPaymentStatus != PaymentStatus.OnTime) {
            currentPaymentStatus = PaymentStatus.OnTime;
            emit PaymentStatusChanged(PaymentStatus.OnTime);
        }

        emit PaymentRecorded(amount, block.timestamp, transactionHash);
    }

    /**
     * @dev Allows worker to raise a dispute
     * Can only be called when contract is active
     */
    function raiseDispute() external onlyWorker onlyWhenActive {
        status = ContractStatus.Disputed;
        emit DisputeRaised(worker);
        emit StatusChanged(ContractStatus.Disputed);
    }

    /**
     * @dev Allows regulator to resolve a dispute
     * @param newStatus The new status to set (Active or Completed)
     */
    function resolveDispute(ContractStatus newStatus) external onlyRegulator {
        require(status == ContractStatus.Disputed, "No active dispute to resolve");
        require(
            newStatus == ContractStatus.Active || newStatus == ContractStatus.Completed,
            "Invalid resolution status"
        );

        status = newStatus;
        emit StatusChanged(newStatus);
    }

    /**
     * @dev Allows either party to mark the contract as completed
     */
    function completeContract() external onlyParties {
        require(
            status == ContractStatus.Active || status == ContractStatus.Disputed,
            "Contract must be active or disputed to complete"
        );

        status = ContractStatus.Completed;
        emit StatusChanged(ContractStatus.Completed);
    }

    /**
     * @dev Returns the total number of payments recorded
     */
    function getPaymentCount() external view returns (uint256) {
        return payments.length;
    }

    /**
     * @dev Returns payment details by index
     * @param index The index of the payment to retrieve
     */
    function getPayment(uint256 index) external view returns (uint256 amount, uint256 timestamp) {
        require(index < payments.length, "Payment index out of bounds");
        Payment memory payment = payments[index];
        return (payment.amount, payment.timestamp);
    }

    /**
     * @dev Returns all payment amounts and timestamps
     */
    function getAllPayments() external view returns (uint256[] memory amounts, uint256[] memory timestamps) {
        uint256 length = payments.length;
        amounts = new uint256[](length);
        timestamps = new uint256[](length);

        for (uint256 i = 0; i < length; i++) {
            amounts[i] = payments[i].amount;
            timestamps[i] = payments[i].timestamp;
        }

        return (amounts, timestamps);
    }

    /**
     * @dev Updates the status of a credential
     * @param credentialId The unique identifier of the credential
     * @param newStatus The new status to set for the credential
     */
    function updateCredentialStatus(string memory credentialId, string memory newStatus) external onlyRegulator {
        require(bytes(credentialId).length > 0, "Credential ID cannot be empty");
        require(bytes(newStatus).length > 0, "Status cannot be empty");

        credentialStatuses[credentialId] = newStatus;
        credentialIssuers[credentialId] = msg.sender;

        emit CredentialStatusUpdated(credentialId, newStatus, msg.sender);
    }

    /**
     * @dev Gets the status of a credential
     * @param credentialId The unique identifier of the credential
     * @return credentialStatus The current status of the credential
     * @return issuer The address of the credential issuer
     */
    function getCredential(string memory credentialId) external view returns (string memory credentialStatus, address issuer) {
        return (credentialStatuses[credentialId], credentialIssuers[credentialId]);
    }

    /**
     * @dev Gets credentials for a worker (placeholder - returns empty for now)
     * @param workerDid The DID of the worker
     * @return An empty array (to be implemented based on specific requirements)
     */
    function getWorkerCredentials(string memory workerDid) external view returns (string[] memory) {
        // This is a placeholder implementation
        // In a real system, you'd need to track which credentials belong to which worker
        string[] memory emptyArray = new string[](0);
        return emptyArray;
    }

    /**
     * @dev Check current payment status and update if overdue
     * @return Current payment status
     */
    function checkPaymentStatus() public returns (PaymentStatus) {
        if (status != ContractStatus.Active) {
            return currentPaymentStatus;
        }

        if (nextPaymentDueDate > 0 && block.timestamp > nextPaymentDueDate && currentPaymentStatus != PaymentStatus.Overdue) {
            currentPaymentStatus = PaymentStatus.Overdue;
            emit PaymentOverdue(nextPaymentDueDate, block.timestamp);
            emit PaymentStatusChanged(PaymentStatus.Overdue);
        }

        return currentPaymentStatus;
    }

    /**
     * @dev Set escrow requirement (Regulator only)
     * @param _amount Required escrow amount
     */
    function setEscrowRequirement(uint256 _amount) external onlyRegulator {
        require(_amount > 0, "Escrow requirement must be greater than zero");
        escrowRequirement = _amount;
        emit EscrowRequirementSet(_amount);
    }

    /**
     * @dev Link escrow contract (Regulator only)
     * @param _escrowContract Address of the escrow contract
     */
    function linkEscrowContract(address _escrowContract) external onlyRegulator {
        require(_escrowContract != address(0), "Escrow contract address cannot be zero");
        escrowContract = _escrowContract;
        emit EscrowLinked(_escrowContract);
    }

    /**
     * @dev Confirm escrow deposit (called by escrow contract)
     * @param _amount Amount deposited
     */
    function confirmEscrowDeposit(uint256 _amount) external {
        require(msg.sender == escrowContract, "Only escrow contract can confirm deposit");
        require(_amount >= escrowRequirement, "Insufficient escrow amount");

        escrowDeposited = true;
        emit EscrowDeposited(escrowContract, _amount);

        // If both parties have signed and escrow is now deposited, activate the contract
        if (workerSigned && employerSigned && status == ContractStatus.Proposed) {
            status = ContractStatus.Active;
            nextPaymentDueDate = block.timestamp + (payFrequency * 1 days);
            emit ContractSigned(worker, employer);
            emit StatusChanged(ContractStatus.Active);
        }
    }

    /**
     * @dev Get contract details including payment status
     * @return _worker Worker address
     * @return _employer Employer address
     * @return _salary Salary amount
     * @return _payFrequency Payment frequency in days
     * @return _nextPaymentDueDate Next payment due date
     * @return _escrowRequirement Required escrow amount
     * @return _escrowDeposited Whether escrow is deposited
     * @return _escrowContract Escrow contract address
     * @return _status Contract status
     * @return _paymentStatus Payment status
     * @return _workerSigned Whether worker has signed
     * @return _employerSigned Whether employer has signed
     */
    function getContractDetails() external view returns (
        address _worker,
        address _employer,
        uint256 _salary,
        uint256 _payFrequency,
        uint256 _nextPaymentDueDate,
        uint256 _escrowRequirement,
        bool _escrowDeposited,
        address _escrowContract,
        ContractStatus _status,
        PaymentStatus _paymentStatus,
        bool _workerSigned,
        bool _employerSigned
    ) {
        return (
            worker,
            employer,
            salary,
            payFrequency,
            nextPaymentDueDate,
            escrowRequirement,
            escrowDeposited,
            escrowContract,
            status,
            currentPaymentStatus,
            workerSigned,
            employerSigned
        );
    }

    /**
     * @dev Get payment details with transaction hash
     * @param index The index of the payment to retrieve
     * @return amount Payment amount
     * @return timestamp Payment timestamp
     * @return transactionHash Real-world transaction hash
     */
    function getPaymentWithHash(uint256 index) external view returns (uint256 amount, uint256 timestamp, string memory transactionHash) {
        require(index < payments.length, "Payment index out of bounds");
        Payment memory payment = payments[index];
        return (payment.amount, payment.timestamp, payment.transactionHash);
    }

    /**
     * @dev Check if contract is ready for activation
     * @return True if both parties signed and escrow deposited
     */
    function isReadyForActivation() external view returns (bool) {
        return workerSigned && employerSigned && escrowDeposited && status == ContractStatus.Proposed;
    }
}

contracts/EscrowContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title EscrowContract
 * @dev Manages escrow deposits for employment contracts to ensure financial guarantees
 * Implements Pillar 2: Financial Incentives & Guarantees
 */
contract EscrowContract is Ownable, ReentrancyGuard {

    // Escrow status enumeration
    enum EscrowStatus {
        Pending,
        Active,
        Released,
        Disputed
    }

    // Escrow deposit structure
    struct EscrowDeposit {
        address employer;
        address worker;
        address employmentContract;
        uint256 depositAmount;
        uint256 depositedAt;
        EscrowStatus status;
        bool isReleased;
        address releasedTo;
        uint256 releasedAt;
        string releaseReason;
    }

    // State variables
    mapping(address => EscrowDeposit) public escrows; // employmentContract => deposit
    mapping(address => uint256) public employerBalances; // employer => total deposited
    mapping(address => address[]) public employerContracts; // employer => contract addresses

    address public regulator; // BMET or trusted authority
    uint256 public minimumDepositRatio = 2; // 2 months salary minimum
    uint256 public totalEscrowed;
    uint256 public totalReleased;

    // Events
    event EscrowDeposited(
        address indexed employmentContract,
        address indexed employer,
        address indexed worker,
        uint256 amount
    );

    event EscrowReleased(
        address indexed employmentContract,
        address indexed releasedTo,
        uint256 amount,
        string reason
    );

    event EscrowDisputed(
        address indexed employmentContract,
        address indexed disputeRaiser
    );

    event RegulatorChanged(address indexed oldRegulator, address indexed newRegulator);
    event MinimumDepositRatioChanged(uint256 oldRatio, uint256 newRatio);

    // Modifiers
    modifier onlyRegulator() {
        require(msg.sender == regulator, "Only regulator can call this function");
        _;
    }

    modifier onlyEmploymentContract() {
        require(escrows[msg.sender].employmentContract == msg.sender, "Only associated employment contract can call");
        _;
    }

    modifier escrowExists(address _employmentContract) {
        require(escrows[_employmentContract].employmentContract != address(0), "Escrow does not exist");
        _;
    }

    /**
     * @dev Constructor sets the regulator and owner
     * @param _regulator Address of the regulator (BMET)
     */
    constructor(address _regulator) Ownable(msg.sender) {
        require(_regulator != address(0), "Regulator address cannot be zero");
        regulator = _regulator;
    }

    /**
     * @dev Deposit escrow for an employment contract
     * @param _employmentContract Address of the employment contract
     * @param _worker Address of the worker
     */
    function depositEscrow(address _employmentContract, address _worker) external payable nonReentrant {
        require(_employmentContract != address(0), "Employment contract address cannot be zero");
        require(_worker != address(0), "Worker address cannot be zero");
        require(msg.value > 0, "Deposit amount must be greater than zero");
        require(escrows[_employmentContract].employmentContract == address(0), "Escrow already exists for this contract");

        // Create escrow deposit
        escrows[_employmentContract] = EscrowDeposit({
            employer: msg.sender,
            worker: _worker,
            employmentContract: _employmentContract,
            depositAmount: msg.value,
            depositedAt: block.timestamp,
            status: EscrowStatus.Active,
            isReleased: false,
            releasedTo: address(0),
            releasedAt: 0,
            releaseReason: ""
        });

        // Update employer balance and contracts
        employerBalances[msg.sender] += msg.value;
        employerContracts[msg.sender].push(_employmentContract);
        totalEscrowed += msg.value;

        // Notify the employment contract about the deposit
        (bool success, ) = _employmentContract.call(
            abi.encodeWithSignature("confirmEscrowDeposit(uint256)", msg.value)
        );
        require(success, "Failed to confirm escrow deposit with employment contract");

        emit EscrowDeposited(_employmentContract, msg.sender, _worker, msg.value);
    }

    /**
     * @dev Release escrow to worker (Regulator only)
     * @param _employmentContract Address of the employment contract
     * @param _reason Reason for release
     */
    function releaseEscrowToWorker(address _employmentContract, string memory _reason) 
        external 
        onlyRegulator 
        escrowExists(_employmentContract) 
        nonReentrant 
    {
        EscrowDeposit storage escrow = escrows[_employmentContract];
        require(escrow.status == EscrowStatus.Active || escrow.status == EscrowStatus.Disputed, "Escrow not available for release");
        require(!escrow.isReleased, "Escrow already released");

        uint256 amount = escrow.depositAmount;
        address worker = escrow.worker;

        // Update escrow status
        escrow.status = EscrowStatus.Released;
        escrow.isReleased = true;
        escrow.releasedTo = worker;
        escrow.releasedAt = block.timestamp;
        escrow.releaseReason = _reason;

        // Update balances
        employerBalances[escrow.employer] -= amount;
        totalReleased += amount;

        // Transfer funds to worker
        (bool success, ) = payable(worker).call{value: amount}("");
        require(success, "Failed to transfer funds to worker");

        emit EscrowReleased(_employmentContract, worker, amount, _reason);
    }

    /**
     * @dev Release escrow to employer (Regulator only)
     * @param _employmentContract Address of the employment contract
     * @param _reason Reason for release
     */
    function releaseEscrowToEmployer(address _employmentContract, string memory _reason) 
        external 
        onlyRegulator 
        escrowExists(_employmentContract) 
        nonReentrant 
    {
        EscrowDeposit storage escrow = escrows[_employmentContract];
        require(escrow.status == EscrowStatus.Active, "Escrow not available for release");
        require(!escrow.isReleased, "Escrow already released");

        uint256 amount = escrow.depositAmount;
        address employer = escrow.employer;

        // Update escrow status
        escrow.status = EscrowStatus.Released;
        escrow.isReleased = true;
        escrow.releasedTo = employer;
        escrow.releasedAt = block.timestamp;
        escrow.releaseReason = _reason;

        // Update balances
        employerBalances[employer] -= amount;
        totalReleased += amount;

        // Transfer funds to employer
        (bool success, ) = payable(employer).call{value: amount}("");
        require(success, "Failed to transfer funds to employer");

        emit EscrowReleased(_employmentContract, employer, amount, _reason);
    }

    /**
     * @dev Handle dispute by marking escrow as disputed
     * @param _employmentContract Address of the employment contract
     */
    function handleDispute(address _employmentContract) 
        external 
        escrowExists(_employmentContract) 
    {
        EscrowDeposit storage escrow = escrows[_employmentContract];
        require(
            msg.sender == escrow.worker || msg.sender == escrow.employer || msg.sender == regulator,
            "Only contract parties or regulator can raise dispute"
        );
        require(escrow.status == EscrowStatus.Active, "Escrow not in active state");
        require(!escrow.isReleased, "Escrow already released");

        escrow.status = EscrowStatus.Disputed;
        emit EscrowDisputed(_employmentContract, msg.sender);
    }

    /**
     * @dev Get escrow status and details
     * @param _employmentContract Address of the employment contract
     * @return Escrow deposit details
     */
    function getEscrowStatus(address _employmentContract) 
        external 
        view 
        escrowExists(_employmentContract)
        returns (EscrowDeposit memory) 
    {
        return escrows[_employmentContract];
    }

    /**
     * @dev Verify if escrow deposit meets minimum requirement
     * @param _employmentContract Address of the employment contract
     * @param _requiredAmount Minimum required amount
     * @return True if deposit is sufficient
     */
    function verifyDeposit(address _employmentContract, uint256 _requiredAmount) 
        external 
        view 
        returns (bool) 
    {
        EscrowDeposit memory escrow = escrows[_employmentContract];
        return escrow.depositAmount >= _requiredAmount && escrow.status == EscrowStatus.Active;
    }

    /**
     * @dev Get employer's total escrowed amount
     * @param _employer Address of the employer
     * @return Total amount escrowed by employer
     */
    function getEmployerBalance(address _employer) external view returns (uint256) {
        return employerBalances[_employer];
    }

    /**
     * @dev Get all employment contracts for an employer
     * @param _employer Address of the employer
     * @return Array of employment contract addresses
     */
    function getEmployerContracts(address _employer) external view returns (address[] memory) {
        return employerContracts[_employer];
    }

    /**
     * @dev Get total escrow statistics
     * @return totalEscrowed Total amount currently escrowed
     * @return totalReleased Total amount released
     * @return activeEscrows Total active escrows
     */
    function getEscrowStatistics() external view returns (uint256, uint256, uint256) {
        // Note: activeEscrows calculation would require additional tracking
        // For now, returning 0 as placeholder
        return (totalEscrowed, totalReleased, 0);
    }

    /**
     * @dev Set minimum deposit ratio (Owner only)
     * @param _ratio New minimum deposit ratio (in months)
     */
    function setMinimumDepositRatio(uint256 _ratio) external onlyOwner {
        require(_ratio > 0, "Ratio must be greater than zero");
        uint256 oldRatio = minimumDepositRatio;
        minimumDepositRatio = _ratio;
        emit MinimumDepositRatioChanged(oldRatio, _ratio);
    }

    /**
     * @dev Change regulator address (Owner only)
     * @param _newRegulator New regulator address
     */
    function setRegulator(address _newRegulator) external onlyOwner {
        require(_newRegulator != address(0), "New regulator address cannot be zero");
        address oldRegulator = regulator;
        regulator = _newRegulator;
        emit RegulatorChanged(oldRegulator, _newRegulator);
    }

    /**
     * @dev Emergency withdrawal function (Owner only)
     * Only for emergency situations, requires careful governance
     * @param _to Address to send funds to
     * @param _amount Amount to withdraw
     */
    function emergencyWithdraw(address payable _to, uint256 _amount) external onlyOwner {
        require(_to != address(0), "Withdrawal address cannot be zero");
        require(_amount <= address(this).balance, "Insufficient contract balance");

        (bool success, ) = _to.call{value: _amount}("");
        require(success, "Emergency withdrawal failed");
    }

    /**
     * @dev Get contract balance
     * @return Current contract balance
     */
    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @dev Fallback function to receive Ether
     */
    receive() external payable {
        // Allow contract to receive Ether
    }
}

contracts/EthereumDIDRegistry.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

contract EthereumDIDRegistry {
    mapping(address => uint) public changed;
    mapping(address => uint) public nonce;

    modifier onlyOwner(address identity, address actor) {
        require(actor == identity || actor == owners[identity], "bad_actor");
        _;
    }

    mapping(address => address) public owners;
    mapping(address => mapping(bytes32 => mapping(address => uint))) public delegates;
    mapping(address => mapping(bytes32 => uint)) public attributes;

    event DIDOwnerChanged(
        address indexed identity,
        address owner,
        uint previousChange
    );

    event DIDDelegateChanged(
        address indexed identity,
        bytes32 delegateType,
        address delegate,
        uint validTo,
        uint previousChange
    );

    event DIDAttributeChanged(
        address indexed identity,
        bytes32 name,
        bytes value,
        uint validTo,
        uint previousChange
    );

    function identityOwner(address identity) public view returns(address) {
        address owner = owners[identity];
        if (owner != address(0x00)) {
            return owner;
        }
        return identity;
    }

    function checkSignature(address identity, uint8 sigV, bytes32 sigR, bytes32 sigS, bytes32 hash) internal returns(address) {
        address signer = ecrecover(hash, sigV, sigR, sigS);
        require(signer == identityOwner(identity), "bad_signature");
        nonce[signer]++;
        return signer;
    }

    function validDelegate(address identity, bytes32 delegateType, address delegate) public view returns(bool) {
        uint validity = delegates[identity][keccak256(abi.encode(delegateType))][delegate];
        return (validity > block.timestamp);
    }

    function changeOwner(address identity, address actor, address newOwner) internal onlyOwner(identity, actor) {
        owners[identity] = newOwner;
        emit DIDOwnerChanged(identity, newOwner, changed[identity]);
        changed[identity] = block.number;
    }

    function changeOwner(address identity, address newOwner) public {
        changeOwner(identity, msg.sender, newOwner);
    }

    function changeOwnerSigned(address identity, uint8 sigV, bytes32 sigR, bytes32 sigS, address newOwner) public {
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0x19), bytes1(0), this, nonce[identityOwner(identity)], identity, "changeOwner", newOwner));
        changeOwner(identity, checkSignature(identity, sigV, sigR, sigS, hash), newOwner);
    }

    function addDelegate(address identity, address actor, bytes32 delegateType, address delegate, uint validity) internal onlyOwner(identity, actor) {
        delegates[identity][keccak256(abi.encode(delegateType))][delegate] = block.timestamp + validity;
        emit DIDDelegateChanged(identity, delegateType, delegate, block.timestamp + validity, changed[identity]);
        changed[identity] = block.number;
    }

    function addDelegate(address identity, bytes32 delegateType, address delegate, uint validity) public {
        addDelegate(identity, msg.sender, delegateType, delegate, validity);
    }

    function addDelegateSigned(address identity, uint8 sigV, bytes32 sigR, bytes32 sigS, bytes32 delegateType, address delegate, uint validity) public {
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0x19), bytes1(0), this, nonce[identityOwner(identity)], identity, "addDelegate", delegateType, delegate, validity));
        addDelegate(identity, checkSignature(identity, sigV, sigR, sigS, hash), delegateType, delegate, validity);
    }

    function revokeDelegate(address identity, address actor, bytes32 delegateType, address delegate) internal onlyOwner(identity, actor) {
        delegates[identity][keccak256(abi.encode(delegateType))][delegate] = block.timestamp;
        emit DIDDelegateChanged(identity, delegateType, delegate, block.timestamp, changed[identity]);
        changed[identity] = block.number;
    }

    function revokeDelegate(address identity, bytes32 delegateType, address delegate) public {
        revokeDelegate(identity, msg.sender, delegateType, delegate);
    }

    function revokeDelegateSigned(address identity, uint8 sigV, bytes32 sigR, bytes32 sigS, bytes32 delegateType, address delegate) public {
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0x19), bytes1(0), this, nonce[identityOwner(identity)], identity, "revokeDelegate", delegateType, delegate));
        revokeDelegate(identity, checkSignature(identity, sigV, sigR, sigS, hash), delegateType, delegate);
    }

    function setAttribute(address identity, address actor, bytes32 name, bytes memory value, uint validity) internal onlyOwner(identity, actor) {
        emit DIDAttributeChanged(identity, name, value, block.timestamp + validity, changed[identity]);
        changed[identity] = block.number;
    }

    function setAttribute(address identity, bytes32 name, bytes memory value, uint validity) public {
        setAttribute(identity, msg.sender, name, value, validity);
    }

    function setAttributeSigned(address identity, uint8 sigV, bytes32 sigR, bytes32 sigS, bytes32 name, bytes memory value, uint validity) public {
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0x19), bytes1(0), this, nonce[identityOwner(identity)], identity, "setAttribute", name, value, validity));
        setAttribute(identity, checkSignature(identity, sigV, sigR, sigS, hash), name, value, validity);
    }

    function revokeAttribute(address identity, address actor, bytes32 name, bytes memory value) internal onlyOwner(identity, actor) {
        emit DIDAttributeChanged(identity, name, value, 0, changed[identity]);
        changed[identity] = block.number;
    }

    function revokeAttribute(address identity, bytes32 name, bytes memory value) public {
        revokeAttribute(identity, msg.sender, name, value);
    }

    function revokeAttributeSigned(address identity, uint8 sigV, bytes32 sigR, bytes32 sigS, bytes32 name, bytes memory value) public {
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0x19), bytes1(0), this, nonce[identityOwner(identity)], identity, "revokeAttribute", name, value));
        revokeAttribute(identity, checkSignature(identity, sigV, sigR, sigS, hash), name, value);
    }
}

contracts/Lock.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// Uncomment this line to use console.log
// import "hardhat/console.sol";

contract Lock {
    uint public unlockTime;
    address payable public owner;

    event Withdrawal(uint amount, uint when);

    constructor(uint _unlockTime) payable {
        require(
            block.timestamp < _unlockTime,
            "Unlock time should be in the future"
        );

        unlockTime = _unlockTime;
        owner = payable(msg.sender);
    }

    function withdraw() public {
        // Uncomment this line, and the import of "hardhat/console.sol", to print a log in your terminal
        // console.log("Unlock time is %o and block timestamp is %o", unlockTime, block.timestamp);

        require(block.timestamp >= unlockTime, "You can't withdraw yet");
        require(msg.sender == owner, "You aren't the owner");

        emit Withdrawal(address(this).balance, block.timestamp);

        owner.transfer(address(this).balance);
    }
}

